package com.wizzadrds.theworldremembers.dream; import com.mojang.serialization.Codec; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import com.wizzadrds.theworldremembers.memory.*; import java.util.*; public final class DreamManager extends SavedData { private static final int MAX_PER_NPC=16; private final Map<UUID,List<Dream>> dreams=new HashMap<>(); private static final Codec<DreamManager> CODEC=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),Dream.CODEC.listOf()).xmap(m->{var x=new DreamManager();x.dreams.putAll(m);return x;},x->x.dreams); private static final SavedDataType<DreamManager> TYPE=new SavedDataType<>(net.minecraft.resources.Identifier.fromNamespaceAndPath("the_world_remembers","dreams"),DreamManager::new,CODEC,null); public static DreamManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new DreamManager():l.getDataStorage().computeIfAbsent(TYPE);} public List<Dream> dreamsOf(UUID id){return List.copyOf(dreams.getOrDefault(id,List.of()));} public Optional<Dream> latest(UUID id){var x=dreams.get(id);return x==null||x.isEmpty()?Optional.empty():Optional.of(x.get(x.size()-1));} public Dream dreamFromMemory(UUID npc,Memory m,long now){DreamType t=classify(m);String summary=switch(t){case FEAR->"You relive a frightening memory: "+m.summary();case NOSTALGIA->"You remember a time that mattered: "+m.summary();case MEMORY->"You relive a memory: "+m.summary();case IMPOSSIBLE->"In the dream, familiar memories become impossible.";};return add(new Dream(npc,t,now,m.gameTime(),m.type().name(),t==DreamType.IMPOSSIBLE,summary));} public Dream dreamImpossible(UUID npc,Memory a,Memory b,long now){return add(new Dream(npc,DreamType.IMPOSSIBLE,now,Math.min(a.gameTime(),b.gameTime()),a.type().name()+"+"+b.type().name(),true,"In the dream, two remembered moments happen at once in an impossible way."));} private Dream add(Dream d){var list=dreams.computeIfAbsent(d.npcId(),k->new ArrayList<>());list.add(d);while(list.size()>MAX_PER_NPC)list.remove(0);setDirty();return d;} private DreamType classify(Memory m){return switch(m.type()){case PLAYER_THREATENED_NPC,PLAYER_ATTACKED_NPC,NPC_DIED,NPC_FAMILY_LOST,GOLEM_KILLED->DreamType.FEAR;case NPC_MARRIED,NPC_BORN,PLAYER_GAVE_BREAD,PLAYER_SAVED_NPC,NPC_INHERITED_ITEM->DreamType.NOSTALGIA;default->DreamType.MEMORY;};} public Optional<Dream> generateForSleepingNpc(UUID npc,long now,List<Memory> memories){if(memories.isEmpty())return Optional.empty();var sorted=memories.stream().sorted(Comparator.comparingLong(Memory::gameTime)).toList();Memory source=sorted.get(sorted.size()-1); if(sorted.size()>1 && (now+Long.hashCode(npc.getMostSignificantBits() ^ npc.getLeastSignificantBits()))%7==0) return Optional.of(dreamImpossible(npc,sorted.get(sorted.size()-2),source,now)); return Optional.of(dreamFromMemory(npc,source,now));}}